package io.github.jesterportfolio.hearth.features;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
final class CutsceneTest {
    @Test void firstIncompleteAlwaysRequiresWatchEvenAfterSeveralStarts(){var s=Cutscene.State.empty();for(int i=0;i<3;i++){s=Cutscene.start(s,UUID.randomUUID(),Cutscene.Choice.WATCH);var old=s;assertThrows(IllegalStateException.class,()->Cutscene.start(old,UUID.randomUUID(),Cutscene.Choice.SKIP));assertFalse(s.completed());assertFalse(Cutscene.choiceRequired(s));}assertEquals(3,s.attempts());}
    @Test void onlyLastConfirmedFrameCompletesFirstViewing(){var id=UUID.randomUUID();var s=Cutscene.start(Cutscene.State.empty(),id,Cutscene.Choice.WATCH);s=Cutscene.advance(s,id,0,3);assertFalse(s.completed());s=Cutscene.advance(s,id,1,3);assertFalse(s.completed());s=Cutscene.advance(s,id,2,3);assertTrue(s.completed());assertTrue(Cutscene.choiceRequired(s));}
    @Test void secondWatchKeepsFutureChoiceAndExplicitSkipIsPermanent(){var id=UUID.randomUUID();var first=Cutscene.advance(Cutscene.start(Cutscene.State.empty(),id,Cutscene.Choice.WATCH),id,0,1);var second=Cutscene.start(first,UUID.randomUUID(),Cutscene.Choice.WATCH);assertTrue(Cutscene.choiceRequired(second));var third=Cutscene.start(second,UUID.randomUUID(),Cutscene.Choice.SKIP);assertTrue(third.skipFuture());assertEquals(3,third.attempts());assertFalse(Cutscene.choiceRequired(third));}
    @Test void requestAndExpectedFramePreventDuplicateProgress(){var id=UUID.randomUUID();var s=Cutscene.start(Cutscene.State.empty(),id,Cutscene.Choice.WATCH);var saved=Cutscene.advance(s,id,0,2);assertEquals(saved,Cutscene.start(saved,id,Cutscene.Choice.WATCH));assertThrows(IllegalStateException.class,()->Cutscene.advance(saved,id,0,2));assertThrows(IllegalStateException.class,()->Cutscene.advance(saved,UUID.randomUUID(),1,2));}
    @Test void replayDoesNotChangeStateRequestOrAttemptCount(){var id=UUID.randomUUID();var s=Cutscene.advance(Cutscene.start(Cutscene.State.empty(),id,Cutscene.Choice.WATCH),id,0,1);assertSame(s,Cutscene.start(s,UUID.randomUUID(),Cutscene.Choice.REPLAY));assertThrows(IllegalStateException.class,()->Cutscene.start(Cutscene.State.empty(),UUID.randomUUID(),Cutscene.Choice.REPLAY));}
    @Test void serializationAndInvalidDataNeverResetProgress(){var s=new Cutscene.State(5,true,true,UUID.randomUUID(),0);assertEquals(s,Cutscene.decode(Cutscene.encode(s)));assertThrows(IllegalArgumentException.class,()->Cutscene.decode(new byte[3]));var corrupt=Arrays.copyOf(Cutscene.encode(s),100);assertThrows(IllegalArgumentException.class,()->Cutscene.decode(corrupt));assertThrows(IllegalArgumentException.class,()->new Cutscene.State(0,false,true,null,0));}
    @Test void changedDefinitionCannotReuseOldCompletion(){var a=new SceneContent.Scene("intro","quest","시작",List.of("공개 A"));var b=new SceneContent.Scene("intro","quest","시작",List.of("다른 공개 내용"));var bytes=SceneProgress.encode(a,new Cutscene.State(1,true,false,UUID.randomUUID(),1));assertTrue(SceneProgress.decode(a,bytes).completed());assertThrows(IllegalArgumentException.class,()->SceneProgress.decode(b,bytes));}
}
